"""Generate an importable, secret-free Postman Desktop collection and screenshot guide."""
import base64,json,uuid
from pathlib import Path
root=Path(__file__).resolve().parents[1]
out=root/'docs/postman/sprint3';out.mkdir(parents=True,exist_ok=True)
files=out/'files';files.mkdir(exist_ok=True)
(files/'evidencia.png').write_bytes(base64.b64decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+a0ioAAAAASUVORK5CYII='))
(files/'archivo-invalido.txt').write_text('Este texto no es una imagen PNG.',encoding='utf-8')
folders=[]
def folder(name,description):
    f={'name':name,'description':description,'item':[]};folders.append(f);return f
def req(f,name,method,path,status=200,body=None,token='tokenA',tests='',pre='',description='',file=None):
    r={'method':method,'header':[],'auth':{'type':'noauth'} if token is None else {'type':'bearer','bearer':[{'key':'token','value':'{{'+token+'}}','type':'string'}]},'url':'{{baseUrl}}'+path,'description':description}
    if body is not None:
        r['header']=[{'key':'Content-Type','value':'application/json'}]
        r['body']={'mode':'raw','raw':json.dumps(body,ensure_ascii=False,indent=2),'options':{'raw':{'language':'json'}}}
    if file:
        r['body']={'mode':'formdata','formdata':[{'key':'file','type':'file','src':'files/'+file,'contentType':'image/png'}]}
    test=f'pm.test("HTTP {status}", () => pm.response.to.have.status({status}));\n'+tests
    events=[{'listen':'test','script':{'type':'text/javascript','exec':test.splitlines()}}]
    if pre:events.insert(0,{'listen':'prerequest','script':{'type':'text/javascript','exec':pre.splitlines()}})
    item={'name':name,'id':str(uuid.uuid5(uuid.NAMESPACE_URL,'instalert-sprint3/'+name)),'request':r,'event':events,'response':[]}
    f['item'].append(item)
    return item
def save(key,field='id'):
    return f'if(pm.response.code<300) pm.collectionVariables.set("{key}",pm.response.json().{field});'
def assertion(name,expression):return f'pm.test({json.dumps(name)},()=>pm.expect({expression}).to.be.true);'
setup=folder('00 - Preparacion (ejecutar primero)','Crea tres cuentas sinteticas nuevas. A: propietario; B: contacto/miembro; C: tercero. No usar cuentas personales. Repetir esta carpeta reinicia los datos de prueba para otra sesión de capturas.')
for role in 'ABC':
    pre=''
    if role=='A':pre='pm.collectionVariables.set("runId",Date.now().toString()+Math.floor(Math.random()*10000));\n'+''.join(f'pm.collectionVariables.unset("{k}");\n' for k in ['incidentId','evidenceId','communityId','privateCommunityId','supportId','contactId','rejectedContactId','grantId','alertId','noticeId'])
    req(setup,f'P0{ord(role)-64} Registrar usuario {role}','POST','/authentication/sign-up',201,{'name':f'Sprint 3 Usuario {role}','email':f'sprint3.{role.lower()}.{{{{runId}}}}@example.com','password':'Sprint3Local2026!'},None,
        tests=f'if(pm.response.code===201){{const s=pm.response.json();pm.collectionVariables.set("token{role}",s.token);pm.collectionVariables.set("account{role}",s.accountId);pm.collectionVariables.set("reference{role}",s.profile.id);}}',pre=pre,description=f'Registrar cuenta de prueba {role}; el token y sus identificadores se guardan automáticamente. No fotografiar la respuesta de registro porque incluye el JWT.')
inc=folder('01 - Incidents (I01 a I16)','Ejecutar en orden después de Preparacion. I15 elimina solamente el reporte sintético creado por I01. Para repetir toda la secuencia, ejecutar nuevamente Preparacion.')
payload={'type':'SPRINT3_POSTMAN','severity':'HIGH','address':'Ubicacion de muestra Lima','description':'Reporte sintetico para la evidencia del Sprint 3','latitude':-12.0464,'longitude':-77.0428,'timeReported':'{{nowIso}}'}
req(inc,'I01 Crear reporte','POST','/incidents',201,payload,tests=save('incidentId')+'\n'+assertion('Reporte ACTIVE con propietario autenticado','pm.response.json().status === "ACTIVE" && pm.response.json().userId === Number(pm.collectionVariables.get("referenceA"))'),description='Crear el reporte de A; capturar Body y respuesta con id, userId, coordenadas y estado ACTIVE.')
req(inc,'I02 Listar reportes paginados','GET','/incidents?paged=true&page=0&size=5',tests=assertion('Respuesta paginada','Array.isArray(pm.response.json().content) && pm.response.json().size===5'),description='Consultar la primera página; mostrar content, page, size y totalElements.')
req(inc,'I03 Consultar reporte por ID','GET','/incidents/{{incidentId}}',tests=assertion('Mismo reporte','pm.response.json().id === Number(pm.collectionVariables.get("incidentId"))'),description='Recuperar el ID guardado automáticamente en I01.')
req(inc,'I04 Filtrar reportes y coordenadas','GET','/incidents?paged=true&type=SPRINT3_POSTMAN&severity=HIGH&status=ACTIVE&minLat=-13&maxLat=-11&minLng=-78&maxLng=-76&page=0&size=5',tests=assertion('Resultados cumplen filtros','pm.response.json().content.length>0 && pm.response.json().content.every(x=>x.type==="SPRINT3_POSTMAN" && x.severity==="HIGH" && x.status==="ACTIVE" && x.latitude>=-13 && x.latitude<=-11 && x.longitude>=-78 && x.longitude<=-76)'),description='En Params mostrar filtros de tipo, severidad, estado y rectángulo geográfico; la respuesta debe cumplirlos.')
req(inc,'I05 Rechazar coordenadas invalidas','POST','/incidents',400,{**payload,'latitude':100},description='Enviar latitud 100; fotografiar el Body inválido y HTTP 400.')
req(inc,'I06 Rechazar propietario suplantado','POST','/incidents',403,{**payload,'userId':'{{referenceB}}'},description='A intenta crear un reporte con el identificador de B. Debe rechazarse con 403.')
req(inc,'I07 Rechazar acceso sin sesion','GET','/incidents',401,token=None,description='No Auth ya está configurado. Demuestra autenticación obligatoria, HTTP 401.')
req(inc,'I08 Rechazar cambio de reporte ajeno','PUT','/incidents/{{incidentId}}/status',403,{'status':'RESOLVED'},'tokenB',description='B intenta modificar el reporte de A. Debe devolver 403.')
req(inc,'I09 Resolver reporte propio','PUT','/incidents/{{incidentId}}/status',200,{'status':'RESOLVED'},tests=assertion('Estado RESOLVED','pm.response.json().status==="RESOLVED"'),description='A cambia su reporte a RESOLVED; mostrar el JSON de entrada y salida.')
req(inc,'I10 Adjuntar evidencia PNG','POST','/incidents/{{incidentId}}/evidences',201,file='evidencia.png',tests=save('evidenceId')+'\n'+assertion('Archivo disponible','pm.response.json().state==="AVAILABLE" && pm.response.json().content_type==="image/png"'),description='Body > form-data > file: seleccionar evidencia.png si Postman solicita permiso al archivo. No agregar Content-Type manualmente. Debe responder AVAILABLE.')
req(inc,'I11 Listar evidencias privadas','GET','/incidents/{{incidentId}}/evidences',tests=assertion('Adjunto registrado','pm.response.json().some(x=>x.id===pm.collectionVariables.get("evidenceId") && x.state==="AVAILABLE")'),description='Mostrar metadatos del archivo privado: nombre, tipo, tamaño y estado AVAILABLE.')
req(inc,'I12 Descargar evidencia propia','GET','/incidents/{{incidentId}}/evidences/{{evidenceId}}',tests='pm.test("Imagen privada y sin cache",()=>{pm.expect(pm.response.headers.get("Content-Type")).to.include("image/png");pm.expect(pm.response.headers.get("Cache-Control")).to.include("no-store");});',description='Mostrar Response > Headers con Content-Type image/png, Content-Disposition y HTTP 200. El Body es binario, no JSON; no es un error.')
req(inc,'I13 Rechazar descarga ajena','GET','/incidents/{{incidentId}}/evidences/{{evidenceId}}',403,token='tokenB',description='B intenta descargar el adjunto privado de A; HTTP 403.')
req(inc,'I14 Rechazar archivo falso','POST','/incidents/{{incidentId}}/evidences',400,file='archivo-invalido.txt',description='El archivo de texto se declara image/png; la firma real no coincide. Mostrar form-data y HTTP 400.')
req(inc,'I15 Eliminar reporte propio','DELETE','/incidents/{{incidentId}}',204,description='A elimina el reporte sintético. HTTP 204 sin cuerpo es correcto. Tomar la captura antes de cambiar de petición.')
req(inc,'I16 Confirmar reporte no disponible','GET','/incidents/{{incidentId}}',404,description='Consultar el ID eliminado en I15. Debe devolver 404.')
com=folder('02 - Communities (C01 a C36)','Ejecutar en orden. Los requests C20 y C26 usan Emergencies únicamente para provocar avisos reales en Communities. Las consultas de bandeja esperan unos segundos porque la entrega es asíncrona. Solo se eliminan comunidades sintéticas creadas aquí.')
req(com,'C01 Crear comunidad publica','POST','/communities',201,{'name':'Comunidad Sprint 3 {{runId}}','description':'Grupo publico de prueba','isPrivate':False},tests=save('communityId')+'\n'+assertion('Propietario y membresia','pm.response.json().ownerId===Number(pm.collectionVariables.get("referenceA")) && pm.response.json().member===true'),description='A crea una comunidad pública. Mostrar id, ownerId, isPrivate y member.')
req(com,'C02 Listar comunidades','GET','/communities?page=0&size=50',tests=assertion('Comunidad creada presente','pm.response.json().some(x=>x.id===Number(pm.collectionVariables.get("communityId")))'),description='Consultar las comunidades visibles para A; respuesta en lista.')
req(com,'C03 Consultar comunidad por ID','GET','/communities/{{communityId}}',tests=assertion('ID correcto','pm.response.json().id===Number(pm.collectionVariables.get("communityId"))'),description='Consultar el ID creado en C01.')
req(com,'C04 Crear comunidad privada','POST','/communities',201,{'name':'Privada Sprint 3 {{runId}}','description':'Solo propietario en este alcance','isPrivate':True},tests=save('privateCommunityId'),description='Crear una comunidad privada de muestra.')
req(com,'C05 Rechazar consulta privada ajena','GET','/communities/{{privateCommunityId}}',403,token='tokenB',description='B no es propietario ni miembro; HTTP 403.')
req(com,'C06 Rechazar apoyo sin membresia','POST','/communities/{{communityId}}/support-requests',403,{'description':'Intento sin membresia'},'tokenB',description='B solicita apoyo antes de unirse. Debe recibir 403.')
req(com,'C07 Unirse a comunidad publica','POST','/communities/{{communityId}}/members/me',204,token='tokenB',description='B se incorpora a la comunidad pública. HTTP 204 sin cuerpo.')
req(com,'C08 Crear solicitud de apoyo','POST','/communities/{{communityId}}/support-requests',201,{'description':'Necesito apoyo vecinal: prueba del Sprint 3'},'tokenB',tests=save('supportId')+'\n'+assertion('Apoyo ACTIVE','pm.response.json().status==="ACTIVE"'),description='Ahora B, como miembro, puede crear una solicitud de apoyo.')
req(com,'C09 Consultar solicitudes de apoyo','GET','/communities/{{communityId}}/support-requests',tests=assertion('Solicitud persistida','pm.response.json().some(x=>x.id===pm.collectionVariables.get("supportId"))'),description='A consulta las solicitudes de su comunidad; mostrar la creada por B.')
req(com,'C10 Resolver solicitud de apoyo','PUT','/communities/{{communityId}}/support-requests/{{supportId}}/resolve',204,description='El propietario A resuelve la solicitud. HTTP 204 sin cuerpo.')
req(com,'C11 Salir de comunidad publica','DELETE','/communities/{{communityId}}/members/me',204,token='tokenB',description='B abandona la comunidad. El propietario A conserva su acceso.')
req(com,'C12 Rechazar eliminacion ajena','DELETE','/communities/{{communityId}}',403,token='tokenC',description='C intenta eliminar la comunidad de A. Debe recibir 403.')
req(com,'C13 Invitar contacto de confianza','POST','/communities/contacts',201,{'accountId':'{{accountB}}'},tests=save('contactId')+'\n'+assertion('Vinculo PENDING','pm.response.json().status==="PENDING"'),description='A invita a B como contacto; el vínculo inicia PENDING.')
req(com,'C14 Listar contactos','GET','/communities/contacts',tests=assertion('Invitacion registrada','pm.response.json().some(x=>x.id===pm.collectionVariables.get("contactId"))'),description='Consultar el vínculo pendiente y los UUID de sus participantes.')
req(com,'C15 Rechazar autoaceptacion','PUT','/communities/contacts/{{contactId}}/accept',403,description='A no puede aceptar su propia invitación en nombre de B; HTTP 403.')
req(com,'C16 Aceptar invitacion recibida','PUT','/communities/contacts/{{contactId}}/accept',204,token='tokenB',description='B acepta explícitamente el vínculo. HTTP 204.')
req(com,'C17 Rechazar monitoreo sin permiso','GET','/communities/monitoring/{{accountA}}',403,token='tokenB',description='Ser contacto aceptado no basta para monitorear: aún no hay permiso explícito; HTTP 403.')
req(com,'C18 Conceder permiso temporal','POST','/communities/monitoring-grants',201,{'accountId':'{{accountB}}','scope':'EMERGENCY_STATUS','expiresAt':'{{grantExpires}}'},tests=save('grantId'),description='A autoriza a B a consultar sus alertas activas durante una hora.')
req(com,'C19 Listar permisos','GET','/communities/monitoring-grants',token='tokenB',tests=assertion('Permiso registrado','pm.response.json().some(x=>x.id===pm.collectionVariables.get("grantId"))'),description='B ve el permiso recibido con propietario, destinatario, alcance y expiración.')
alert={'type':'SPRINT3_POSTMAN','latitude':-12.0464,'longitude':-77.0428,'accuracyM':15,'locationRecordedAt':'{{nowIso}}'}
r=req(com,'C20 Generar alerta para probar avisos','POST','/emergencies',201,alert,tests=save('alertId')+'\n'+assertion('Alerta ACTIVE','pm.response.json().status==="ACTIVE"'),pre='pm.variables.set("eventKey",pm.variables.replaceIn("{{$guid}}"));',description='Petición auxiliar a Emergencies: genera una alerta real de A que debe llegar a la bandeja de B. No simula ni inyecta eventos internos.')
r['request']['header'].append({'key':'Idempotency-Key','value':'{{eventKey}}'})
notice_test='''if(pm.response.code===200){const notices=pm.response.json();const n=notices.find(x=>x.alert_id===pm.collectionVariables.get("alertId") && x.event_type==="EmergencyAlertCreated");pm.test("Aviso real recibido exactamente una vez",()=>pm.expect(notices.filter(x=>x.alert_id===pm.collectionVariables.get("alertId") && x.event_type==="EmergencyAlertCreated")).to.have.lengthOf(1));if(n)pm.collectionVariables.set("noticeId",n.id);}'''
req(com,'C21 Consultar aviso recibido','GET','/communities/notifications',token='tokenB',tests=notice_test,pre='setTimeout(()=>{},3000);',description='Espera tres segundos y consulta la bandeja de B. Debe contener EmergencyAlertCreated y el alert_id de C20. Si aún no aparece, espera y repite solo C21.')
req(com,'C22 Consultar monitoreo autorizado','GET','/communities/monitoring/{{accountA}}',token='tokenB',tests=assertion('Alerta activa autorizada','pm.response.json().some(x=>x.id===pm.collectionVariables.get("alertId") && x.status==="ACTIVE")'),description='Con vínculo y permiso vigentes, B obtiene la alerta activa real de A.')
req(com,'C23 Marcar aviso como leido','PUT','/communities/notifications/{{noticeId}}/read',204,token='tokenB',description='B marca el aviso de C21 como leído. HTTP 204.')
req(com,'C24 Consultar preferencias','GET','/communities/notification-preferences',token='tokenB',tests=assertion('Preferencia inicial habilitada','pm.response.json().enabled===true'),description='B consulta si está habilitada la recepción de nuevos avisos.')
req(com,'C25 Desactivar nuevos avisos','PUT','/communities/notification-preferences',204,{'enabled':False},'tokenB',description='B desactiva recepción de nuevas alertas. Una cancelación de una alerta ya recibida todavía debe notificarse.')
req(com,'C26 Cancelar alerta ya notificada','PATCH','/emergencies/{{alertId}}',200,{'status':'CANCELLED'},tests=assertion('Cancelacion persistida','pm.response.json().status==="CANCELLED"'),description='Petición auxiliar: A cancela la alerta de C20 para comprobar el aviso de cancelación.')
req(com,'C27 Consultar aviso de cancelacion','GET','/communities/notifications',token='tokenB',pre='setTimeout(()=>{},3000);',tests='''if(pm.response.code===200){const ns=pm.response.json().filter(x=>x.alert_id===pm.collectionVariables.get("alertId"));pm.test("Creacion y cancelacion sin duplicados",()=>{pm.expect(ns).to.have.lengthOf(2);pm.expect(ns.some(x=>x.event_type==="EmergencyAlertCancelled")).to.be.true;pm.expect(ns.find(x=>x.event_type==="EmergencyAlertCreated").read_at).not.to.equal(null);});}''',description='La bandeja debe tener EmergencyAlertCreated y EmergencyAlertCancelled para el mismo ID, pese al opt-out. El aviso original conserva read_at. Si falta la cancelación, espera y repite solo C27.')
req(com,'C28 Revocar permiso de monitoreo','DELETE','/communities/monitoring-grants/{{grantId}}',204,description='A revoca el permiso concedido en C18.')
req(com,'C29 Rechazar monitoreo revocado','GET','/communities/monitoring/{{accountA}}',403,token='tokenB',description='B ya no puede consultar las alertas de A. HTTP 403.')
req(com,'C30 Revocar contacto','DELETE','/communities/contacts/{{contactId}}',204,description='A revoca el vínculo de confianza con B.')
req(com,'C31 Invitar segundo contacto','POST','/communities/contacts',201,{'accountId':'{{accountC}}'},tests=save('rejectedContactId'),description='Crear otra invitación A a C para probar rechazo sin alterar la secuencia anterior.')
req(com,'C32 Rechazar invitacion recibida','PUT','/communities/contacts/{{rejectedContactId}}/reject',204,token='tokenC',description='C rechaza la invitación recibida; HTTP 204.')
req(com,'C33 Confirmar estados de contactos','GET','/communities/contacts',tests=assertion('REVOKED y REJECTED persistidos','pm.response.json().some(x=>x.id===pm.collectionVariables.get("contactId") && x.status==="REVOKED") && pm.response.json().some(x=>x.id===pm.collectionVariables.get("rejectedContactId") && x.status==="REJECTED")'),description='Mostrar el primer vínculo REVOKED y el segundo REJECTED.')
req(com,'C34 Rechazar bandeja sin sesion','GET','/communities/notifications',401,token=None,description='No Auth ya configurado. Sin sesión no se puede consultar la bandeja; HTTP 401.')
req(com,'C35 Eliminar comunidad publica propia','DELETE','/communities/{{communityId}}',204,description='A elimina únicamente la comunidad de prueba de C01. También elimina sus solicitudes de apoyo por la FK.')
req(com,'C36 Eliminar comunidad privada propia','DELETE','/communities/{{privateCommunityId}}',204,description='A elimina la comunidad privada sintética de C04.')
variables=['runId','tokenA','tokenB','tokenC','accountA','accountB','accountC','referenceA','referenceB','referenceC','incidentId','evidenceId','communityId','privateCommunityId','supportId','contactId','rejectedContactId','grantId','alertId','noticeId']
collection={'info':{'_postman_id':str(uuid.uuid5(uuid.NAMESPACE_URL,'instalert-sprint3')),'name':'InstAlert Sprint 3 - Incidents y Communities','schema':'https://schema.getpostman.com/json/collection/v2.1.0/collection.json','description':'Evidencias locales del Sprint 3. Ejecutar Preparacion, Incidents y Communities en orden. Variables y tokens se encadenan automáticamente; no exportar valores de sesión. Base Docker Gateway localhost:8085/api/v1. Solo se crean y eliminan fixtures sintéticos. Ver GUIA_CAPTURAS.md.'},'variable':[{'key':'baseUrl','value':'http://localhost:8085/api/v1','type':'string'}]+[{'key':k,'value':'','type':'string'} for k in variables],'event':[{'listen':'prerequest','script':{'type':'text/javascript','exec':['pm.variables.set("nowIso",new Date().toISOString());','pm.variables.set("grantExpires",new Date(Date.now()+3600000).toISOString());']}}],'item':folders}
(out/'InstAlert-Sprint3.postman_collection.json').write_text(json.dumps(collection,ensure_ascii=False,indent=2),encoding='utf-8')
guide=['# Postman Sprint 3: instrucciones para capturas','', '1. Abrir Postman → Import → Files y seleccionar `InstAlert-Sprint3.postman_collection.json`.','2. Expandir la colección. Se puede dejar `No Environment`: baseUrl y encadenamiento pertenecen a la colección.','3. Ejecutar P01, P02 y P03 de la carpeta 00, en ese orden. No fotografiar sus JWT.','4. Para cada evidencia abrir la petición, no cambiar método, URL, autorización ni Body; pulsar Send.','5. Mostrar URL/método, Body o Params y la respuesta con el código HTTP. Arrastrar el separador horizontal para dar espacio a la respuesta.','6. Guardar capturas con el mismo prefijo I01… I16 y C01… C36. En 204 la respuesta está vacía; es correcto. En 400/401/403/404 se prueba un rechazo esperado.','7. Para I10/I14, si Postman no encuentra el archivo, ir a Body → form-data → file → Select Files y elegir el archivo correspondiente en la subcarpeta files. El campo es de tipo File. No agregar Content-Type en Headers.','8. Completar Incidents antes de Communities. Las secuencias usan cuentas de prueba, nunca datos personales. Para comenzar desde cero, volver a ejecutar la preparación; no repetir DELETE ni los requests que crean contactos aislados esperando otro resultado.','9. Los tokens caducan: para sesiones largas iniciar nuevamente la preparación y repetir cada bloque. No publicar ni exportar valores de tokenA/tokenB/tokenC.','10. Las capturas muestran ejecución HTTP local, no despliegue cloud ni pruebas de carga. C20/C26 son auxiliares de Emergencies para verificar los avisos de Communities.','']
for f in folders[1:]:
    guide+=['## '+f['name'],'']
    for item in f['item']:
        r=item['request'];code=item['event'][-1]['script']['exec'][0].split('HTTP ')[1].split('"')[0]
        guide+=['### '+item['name'],f'1. Seleccionar **{item["name"]}**.',f'2. Método y ruta: `{r["method"]} {r["url"]}`.',f'3. {r["description"]}',f'4. Pulsar **Send**. Resultado esperado: **HTTP {code}**; comprobar **Test Results**.',f'5. Tomar captura y guardar como `{item["name"].split()[0]}-{item["name"][4:].replace(" ","-")}.jpg`.','']
(out/'GUIA_CAPTURAS.md').write_text('\n'.join(guide),encoding='utf-8')
print('Generated:',out, '| Requests:',sum(len(f['item']) for f in folders))
